import{c as a,ah as n,L as i,O as p}from"./chunks/framework.YKVbmyBD.js";const r=JSON.parse('{"title":"磁盘管理","description":"","frontmatter":{},"headers":[],"relativePath":"fovlin-notes/linux-guide/configure-system/disk-manage.md","filePath":"fovlin-notes/linux-guide/configure-system/disk-manage.md"}'),e={name:"fovlin-notes/linux-guide/configure-system/disk-manage.md"};function t(l,s,d,h,c,k){return n(),i("div",null,[...s[0]||(s[0]=[p(`<h1 id="磁盘管理" tabindex="-1">磁盘管理 <a class="header-anchor" href="#磁盘管理" aria-label="Permalink to “磁盘管理”">​</a></h1><p>虽然一些发行版会配备图形化的磁盘管理工具，但手动管理仍然是 Linux 的必学项之一。</p><p>本文汇总了如何去手动管理磁盘，进行分区，自动挂载。</p><p>Linux 下常用的分区工具有，命令行的 <code>fdisk</code> <code>parted</code> <code>cfdisk</code> 以及图形化的 <code>gparted</code>，本文对磁盘的操作以 <code>fdisk</code> 为例。</p><div style="background-color:rgb(255 0 0 / 0.15);padding:4px 12px;border-radius:16px;"><p><strong>注意!</strong></p><p>本文涉及到的大量命令需要使用 root 权限，请以 root 身份执行下列命令。</p><p>本文涵盖的所有操作在操作不当的前提下，会导致数据丢失，请务必在虚拟机中练习！</p></div><h2 id="磁盘分区" tabindex="-1">磁盘分区 <a class="header-anchor" href="#磁盘分区" aria-label="Permalink to “磁盘分区”">​</a></h2><p>使用 <code>lsblk</code> 可以查看连接在此计算机上的磁盘设备:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lsblk</span></span></code></pre></div><p>将产生以下类似输出</p><div class="language-log"><button title="Copy Code" class="copy"></button><span class="lang">log</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NAME        MAJ:MIN RM   SIZE RO TYPE MOUNTPOINTS</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">nvme0n1     </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">259</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 953</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.9G  </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> disk </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">├─nvme0n1p1 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">259</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  14</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.9G  </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> part [SWAP]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">├─nvme0n1p2 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">259</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   250G  </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> part /</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">├─nvme0n1p3 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">259</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">     1G  </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> part /boot</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">└─nvme0n1p4 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">259</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 326</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.1G  </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> part /home</span></span></code></pre></div><p>所有的磁盘设备在 <code>/dev</code> 路径下，使用 <code>fdisk</code> 工具来操作此磁盘。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fdisk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/nvme0n1</span></span></code></pre></div><p>这将会进入一个交互式的命令行模式，输入 <code>m</code> 将打印操作选项:</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>  GPT</span></span>
<span class="line"><span>   M   进入 保护/混合 MBR</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  常规</span></span>
<span class="line"><span>   d   删除分区</span></span>
<span class="line"><span>   F   列出未分区的空闲区</span></span>
<span class="line"><span>   l   列出已知分区类型</span></span>
<span class="line"><span>   n   添加新分区</span></span>
<span class="line"><span>   p   打印分区表</span></span>
<span class="line"><span>   t   更改分区类型</span></span>
<span class="line"><span>   v   检查分区表</span></span>
<span class="line"><span>   i   打印某个分区的相关信息</span></span>
<span class="line"><span>   e   调整分区大小</span></span>
<span class="line"><span>   T   discard (trim) sectors</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  杂项</span></span>
<span class="line"><span>   m   打印此菜单</span></span>
<span class="line"><span>   x   更多功能(仅限专业人员)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  脚本</span></span>
<span class="line"><span>   I   从 sfdisk 脚本文件加载磁盘布局</span></span>
<span class="line"><span>   O   将磁盘布局转储为 sfdisk 脚本文件</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  保存并退出</span></span>
<span class="line"><span>   w   将分区表写入磁盘并退出</span></span>
<span class="line"><span>   q   退出而不保存更改</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  新建空磁盘标签</span></span>
<span class="line"><span>   g   新建一份 GPT 分区表</span></span>
<span class="line"><span>   G   新建一份空 GPT (IRIX) 分区表</span></span>
<span class="line"><span>   o   新建一份的空 DOS（MBR）分区表</span></span>
<span class="line"><span>   s   新建一份空 Sun 分区表</span></span></code></pre></div><p>例如要新建一个分区，用来存储一些文件，首先输入 <code>p</code> 打印当前的分区表:</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>命令(输入 m 获取帮助):p</span></span>
<span class="line"><span>Disk /dev/nvme0n1:953.87 GiB，1024209543168 字节，2000409264 个扇区</span></span>
<span class="line"><span>磁盘型号:WD PC SN560 SDDPNQE-1T00-1102           </span></span>
<span class="line"><span>单元:扇区 / 1 * 512 = 512 字节</span></span>
<span class="line"><span>扇区大小(逻辑/物理):512 字节 / 512 字节</span></span>
<span class="line"><span>I/O 大小(最小/最佳):512 字节 / 512 字节</span></span>
<span class="line"><span>磁盘标签类型:gpt</span></span>
<span class="line"><span>磁盘标识符:197A8B74-97C4-47DB-AB74-9BC51952A01E</span></span>
<span class="line"><span></span></span>
<span class="line"><span>设备                起点       末尾      扇区   大小 类型</span></span>
<span class="line"><span>/dev/nvme0n1p1      2048   31252479  31250432  14.9G Linux swap</span></span>
<span class="line"><span>/dev/nvme0n1p2  33454080  557742079 524288000   250G Linux 文件系统</span></span>
<span class="line"><span>/dev/nvme0n1p3  31252480   33454079   2201600     1G EFI 系统</span></span>
<span class="line"><span>/dev/nvme0n1p4 557742080 1241565183 683823104 326.1G Linux 文件系统</span></span></code></pre></div><p>输入 <code>F</code> 查看剩余空间:</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>命令(输入 m 获取帮助):F</span></span>
<span class="line"><span></span></span>
<span class="line"><span>未分区的空间 /dev/nvme0n1:361.85 GiB，388528152064 个字节，758844047 个扇区</span></span>
<span class="line"><span>单元:扇区 / 1 * 512 = 512 字节</span></span>
<span class="line"><span>扇区大小(逻辑/物理):512 字节 / 512 字节</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      起点       末尾      扇区   大小</span></span>
<span class="line"><span>1241565184 2000409230 758844047 361.8G</span></span></code></pre></div><p>可见有较大的剩余空间，使用 <code>n</code> 创建一个新分区，分区号最好按每个分区的起点终点的顺序排列:</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>命令(输入 m 获取帮助):n</span></span>
<span class="line"><span>分区号 (5-128, 默认  5): 5</span></span>
<span class="line"><span>第一个扇区 (1241565184-2000409230, 默认 1241565184): </span></span>
<span class="line"><span>最后一个扇区，+/-sectors 或 +size{K,M,G,T,P} (1241565184-2000409230, 默认 2000408575):</span></span></code></pre></div><p>填写大小时候，填写终点对应的数字，或填写一个尺寸的变化量，例如 <code>+128G</code> <code>+12800M</code> 等，若要将本扇区的全部空闲空间应用，直接填写本扇区的终点，或直接回车，因为默认为本扇区的终点:</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>命令(输入 m 获取帮助):n</span></span>
<span class="line"><span>分区号 (5-128, 默认  5): 5</span></span>
<span class="line"><span>第一个扇区 (1241565184-2000409230, 默认 1241565184): </span></span>
<span class="line"><span>最后一个扇区，+/-sectors 或 +size{K,M,G,T,P} (1241565184-2000409230, 默认 2000408575): </span></span>
<span class="line"><span></span></span>
<span class="line"><span>创建了一个新分区 5，类型为“Linux filesystem”，大小为 361.8 GiB。</span></span>
<span class="line"><span>分区 #5 包含一个 ext4 签名。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>您想移除该签名吗？是[Y]/否[N]:Y</span></span>
<span class="line"><span></span></span>
<span class="line"><span>写入命令将移除该签名。</span></span></code></pre></div><p>随后写入操作，输入 <code>w</code>:</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>命令(输入 m 获取帮助):w</span></span>
<span class="line"><span>分区表已调整。</span></span>
<span class="line"><span>正在同步磁盘。</span></span></code></pre></div><p>再使用 <code>lablk</code> 查看本计算机上的磁盘设备，将发现出现了新的分区:</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>NAME        MAJ:MIN RM   SIZE RO TYPE MOUNTPOINTS</span></span>
<span class="line"><span>nvme0n1     259:0    0 953.9G  0 disk </span></span>
<span class="line"><span>├─nvme0n1p1 259:1    0  14.9G  0 part [SWAP]</span></span>
<span class="line"><span>├─nvme0n1p2 259:2    0   250G  0 part /</span></span>
<span class="line"><span>├─nvme0n1p3 259:3    0     1G  0 part /boot</span></span>
<span class="line"><span>├─nvme0n1p4 259:4    0 326.1G  0 part /home</span></span>
<span class="line"><span>└─nvme0n1p5 259:5    0 361.8G  0 part &lt;--新分区!</span></span></code></pre></div><h2 id="格式化分区" tabindex="-1">格式化分区 <a class="header-anchor" href="#格式化分区" aria-label="Permalink to “格式化分区”">​</a></h2><p>在挂载之前，确保分区的文件系统类型为受支持的文件系统，如 <code>ext4</code>，否则无法挂载。</p><p>查看分区的文件系统，有以下几种方法:</p><p><strong>使用 <code>lsblk -f</code> 查看所有分区文件系统:</strong></p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>NAME        FSTYPE FSVER LABEL UUID                                 FSAVAIL FSUSE% MOUNTPOINTS</span></span>
<span class="line"><span>nvme0n1                                                                            </span></span>
<span class="line"><span>├─nvme0n1p1 swap   1           8942c221-27c8-4f5c-ad86-d31afade6458                [SWAP]</span></span>
<span class="line"><span>├─nvme0n1p2 ext4   1.0         397e208d-b1d0-42db-9e69-cd094b41c132  215.7G     7% /</span></span>
<span class="line"><span>├─nvme0n1p3 vfat   FAT32       A9FE-938A                            1016.9M     5% /boot</span></span>
<span class="line"><span>├─nvme0n1p4 ext4   1.0         4917aab9-8e61-4fc9-a4f3-ec2bb0a4d094  286.9G     5% /home</span></span>
<span class="line"><span>└─nvme0n1p5</span></span></code></pre></div><p><strong>使用 <code>parted -l</code> 查看分区文件系统:</strong></p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>型号：WD PC SN560 SDDPNQE-1T00-1102 (nvme)</span></span>
<span class="line"><span>磁盘 /dev/nvme0n1：1024GB</span></span>
<span class="line"><span>扇区大小 (逻辑/物理)：512B/512B</span></span>
<span class="line"><span>分区表：gpt</span></span>
<span class="line"><span>磁盘标志：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>编号   起始点   结束点   大小    文件系统         名称                  标志</span></span>
<span class="line"><span> 1    1049kB  16.0GB  16.0GB  linux-swap(v1)                        交换</span></span>
<span class="line"><span> 3    16.0GB  17.1GB  1127MB  fat32           EFI System Partition  启动, esp</span></span>
<span class="line"><span> 2    17.1GB  286GB   268GB   ext4</span></span>
<span class="line"><span> 4    286GB   636GB   350GB   ext4</span></span>
<span class="line"><span> 5    636GB   1024GB  389GB</span></span></code></pre></div><p>对于新分区，需要先将其格式化才能挂载，假设将 <code>nvme0n1p5</code> 格式化为 <code>ext4</code> 文件系统。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkfs.ext4</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/nvme0n1p5</span></span></code></pre></div><p>至此成功格式化。</p><h2 id="挂载磁盘" tabindex="-1">挂载磁盘 <a class="header-anchor" href="#挂载磁盘" aria-label="Permalink to “挂载磁盘”">​</a></h2><p>将现有的受支持的文件系统挂载到系统中，使用 <code>mount</code> 命令，假设有一块名为 <code>nvme0n1p5</code> 的 <code>ext4</code> 文件系统的分区，并挂载在 <code>/mnt</code> 目录，使用以下命令:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mount</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --mkdir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/nvme0n1p5</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /mnt</span></span></code></pre></div><blockquote><p><code>--mkdir</code> 参数可以在挂载点目录不存在时自动创建该目录。</p></blockquote><blockquote><p>挂载后，该文件夹内原文件将会被覆盖，但并不会被替换，因为该路径的存储方式只是更换了一个扇区，同理的，卸载后目录内原文件会恢复。</p></blockquote><p>使用 <code>lsblk</code> 将会查找到该分区对应的挂载点。</p><p>要想开机自动挂载硬盘，需要依靠 <code>/etc/fstab</code> 文件，系统启动会读取该文件内的内容，并挂载写入该文件的文件系统。</p><p>示例文件如下：</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># /dev/nvme0n1p3</span></span>
<span class="line"><span>UUID=fef38f12-8b93-4609-8d14-e2fb766504d7       /              ext4             rw,relatime     0 1</span></span>
<span class="line"><span></span></span>
<span class="line"><span># /dev/nvme0n1p1</span></span>
<span class="line"><span>UUID=8B04-0289          /boot           vfat            rw,relatime,fmask=0022,dmask=0022,codepage=437,iocharset=ascii,shortname=mixed,utf8,errors=remount-ro   0 2</span></span>
<span class="line"><span></span></span>
<span class="line"><span># /dev/nvme0n1p4</span></span>
<span class="line"><span>UUID=915304a9-718d-4299-a443-c26d73cdfa16       /home          ext4             rw,relatime     0 2</span></span>
<span class="line"><span></span></span>
<span class="line"><span># /dev/nvme0n1p2</span></span>
<span class="line"><span>UUID=2e5a6b13-6e00-464c-8893-0078a6f437c4       none           swap             defaults        0 0</span></span></code></pre></div><p>一行代表一个挂载点，系统的启动依靠该文件，写入该文件的内容格式如下：</p><p><code>设备</code> <code>挂载点</code> <code>文件系统类型</code> <code>挂载选项</code> <code>dump</code> <code>fsck</code></p><p>各项含义如下：</p><ul><li><p><strong>设备:</strong></p><p>推荐使用 UUID 或 LABEL，避免 /dev/sdX 变化导致挂载失败。</p><p>设备的 UUID 可以通过 <code>blkid</code> 命令获取。</p></li><li><p><strong>挂载点:</strong></p><p>如 /、/home、/mnt/data，swap 分区用 none。</p></li><li><p><strong>文件系统类型:</strong></p><p>ext4、xfs、ntfs、vfat、nfs、cifs、iso9660、swap 等。</p></li><li><p><strong>挂载选项:</strong></p><p>控制挂载时的行为，如要选择多个选项，应使用 <code>,</code> 分开，可用项如下:</p></li></ul><table tabindex="0"><thead><tr><th>可用选项</th><th>描述</th></tr></thead><tbody><tr><td>defaults</td><td>一组默认值，通常 rw,suid,dev,exec,auto,nouser,async,relatime。</td></tr><tr><td>auto / noauto</td><td>有 auto 文件系统会在启动时自动挂载，或者通过以下方式挂载: mount -a。同 noauto 只有在明确指示的情况下才会挂载，这对于光驱或只想按需挂载的分区非常有用。</td></tr><tr><td>rw / ro</td><td>强制挂载点以读写或只读模式运行。将某项标记为 rw 当系统或驱动程序倾向于挂载它时，这可能很有用。 默认只读这种情况有时会发生在 NTFS 或可移动介质上。</td></tr><tr><td>exec / noexec</td><td>允许或阻止在该文件系统上执行二进制文件。</td></tr><tr><td>dev / nodev</td><td>控制是否在文件系统中解释特殊设备（字符和块）。</td></tr><tr><td>suid / nosuid</td><td>启用或禁用 SUID 和 SGID 位的效果。</td></tr><tr><td>user, users, nouser</td><td>他们决定谁可以组装和拆卸。user 它允许普通用户挂载文件系统，并且只有他们可以卸载它，而 users 它允许相应组中的任何成员对其进行拆解。在这两种情况下，这都是默认设置，nouser 仅限root用户挂载。</td></tr><tr><td>owner （在 Linux 系统上）</td><td>允许设备所有者（不一定是 root 用户）挂载该设备。</td></tr><tr><td>sync / async</td><td>定义输入/输出操作是同步执行还是异步执行。</td></tr><tr><td>noatime, nodiratime, relatime, strictatime, lazytime</td><td>它们控制访问分区的更新方式，减少这些写入操作可以显著提高性能并降低 SSD 的损耗。</td></tr><tr><td>nofail</td><td>这样可以防止系统将设备挂载失败标记为严重错误。这对于……非常有用。 外部 磁盘或辅助分区 可能不存在；防止启动检查失败。</td></tr></tbody></table><ul><li><p><strong>dump:</strong></p><p>备份设置，0=不备份，1=根分区备份，2=其他分区备份。</p></li><li><p><strong>fsck:</strong></p><p>检查设备，0=不检查，1=根分区优先检查，2=其他分区顺序检查。</p></li></ul><p>假设我们要设置自动挂载 <code>nvme0n1p5</code> 到 <code>/home</code>，首先获取分区的 UUID:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blkid</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/nvme0n1p5</span></span></code></pre></div><p>得到以下输出:</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/dev/nvme0n1p4: LABEL=&quot;Files&quot; BLOCK_SIZE=&quot;512&quot; UUID=&quot;7CFC1A1BFC19CFEE&quot; TYPE=&quot;ntfs&quot; PARTLABEL=&quot;Basic data partition&quot; PARTUUID=&quot;6bf9b792-5a7a-4a6e-a665-2d8c4589ae1f&quot;</span></span></code></pre></div><p>能看到，设备 UUID 条目为 <code>PARTUUID=&quot;6bf9b792-5a7a-4a6e-a665-2d8c4589ae1f&quot;</code></p><p>随后设置自动挂载，将以下内容写入 <code>/etc/fstab</code> 文件：</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>UUID=6bf9b792-5a7a-4a6e-a665-2d8c4589ae1f  /home  ext4  default  0  2</span></span></code></pre></div><p>可以直接使用 <code>echo</code> 命令追加到行尾：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;UUID=6bf9b792-5a7a-4a6e-a665-2d8c4589ae1f  /home  ext4  default  0  2&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/fstab</span></span></code></pre></div><p>写入完成后执行以下命令:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mount</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span></span></code></pre></div><p>这将重新读取 fstab 文件并挂载文件内所写的设备，若无报错即成功。</p>`,63)])])}const g=a(e,[["render",t]]);export{r as __pageData,g as default};
